import React from 'react';

function Services() {
  return (
    <section className="services" style={{ padding: '50px', textAlign: 'center' }}>
      <h2>Our Services</h2>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        <li>Custom Furniture</li>
        <li>Home Renovation</li>
        <li>Wood Repairs</li>
        <li>Interior Design Carpentry</li>
      </ul>
    </section>
  );
}

export default Services;
